// control_rom.v — horizontal microcode store.
// 256 entries addressed by {opcode[4:0], tstate[2:0]} -> CW_WIDTH control word.
// Initialised from microcode/microcode.mem (generated by gen_microcode.py).
`default_nettype none
module control_rom #(
    parameter MEM_FILE = "microcode.mem",
    parameter CW_WIDTH = 40
) (
    input  wire [7:0]            addr,
    output wire [CW_WIDTH-1:0]   cw
);
    reg [CW_WIDTH-1:0] rom [0:255];
    initial $readmemh(MEM_FILE, rom);
    assign cw = rom[addr];
endmodule
`default_nettype wire
